script:
(function () {
  'use strict';

  var btnRun = document.getElementById('btnRunCheck');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var checkVideo = document.getElementById('checkVideo');
  var hiddenCanvas = document.getElementById('hiddenCanvas');
  var ledSelect = document.getElementById('ledSelect');
  var running = false;
  var activeStream = null;
  var lastStreamOk = null; // true = live track, false = failed, null = not run
  var SAMPLE_MS = 3000;
  var chk = {};
  ['StreamResult', 'NextStep', 'Permission', 'Cameras', 'Led', 'Resolution', 'Megapixels', 'Standard', 'Aspect', 'FrameRate', 'FpsCheck', 'Lighting', 'ImageMode', 'Mic'].forEach(function (k) {
    chk[k] = document.getElementById('chk' + k);
  });
  var STANDARDS = [
    ['8K UHD', 7680, 4320], ['DCI 4K', 4096, 2160], ['4K UHD', 3840, 2160], ['QHD (1440p)', 2560, 1440],
    ['WUXGA', 1920, 1200], ['Full HD (1080p)', 1920, 1080], ['UXGA', 1600, 1200], ['HD+ (900p)', 1600, 900],
    ['SXGA', 1280, 1024], ['WXGA', 1280, 800], ['HD (720p)', 1280, 720], ['XGA', 1024, 768], ['SVGA', 800, 600],
    ['VGA', 640, 480], ['nHD', 640, 360], ['CIF', 352, 288], ['QVGA', 320, 240], ['QQVGA', 160, 120],
  ];

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function setChk(k, v) { chk[k].textContent = v; }

  function gcd(a, b) { return b ? gcd(b, a % b) : a; }

  function videoStandard(w, h) {
    var a = Math.max(w, h), b = Math.min(w, h), best = null, bestDiff = Infinity;
    for (var i = 0; i < STANDARDS.length; i++) {
      if (STANDARDS[i][1] === a && STANDARDS[i][2] === b) return STANDARDS[i][0];
      var diff = Math.abs(STANDARDS[i][1] * STANDARDS[i][2] - a * b);
      if (diff < bestDiff) { bestDiff = diff; best = STANDARDS[i][0]; }
    }
    return '≈ ' + best;
  }

  // Permissions API state for this site's camera ('granted' / 'prompt' /
  // 'denied'); Firefox and Safari may not support querying 'camera'.
  function readPermission() {
    if (!navigator.permissions || !navigator.permissions.query) { setChk('Permission', 'Not reported by this browser'); return; }
    navigator.permissions.query({ name: 'camera' }).then(function (status) {
      var label = { granted: 'Granted (allowed)', prompt: 'Prompt (will ask)', denied: 'Denied (blocked)' };
      setChk('Permission', label[status.state] || status.state);
      status.onchange = function () { setChk('Permission', label[status.state] || status.state); };
    }).catch(function () { setChk('Permission', 'Not reported by this browser'); });
  }

  function readDevices(track) {
    if (!navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(function (devices) {
      var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
      var virtualCount = cams.filter(function (d) { return /virtual|obs|snap|manycam|xsplit|droidcam|epoccam|nvidia broadcast/i.test(d.label); }).length;
      setChk('Cameras', cams.length + (virtualCount ? ' (' + virtualCount + ' virtual)' : '') + (cams.length && !cams[0].label ? ' — names hidden until access is allowed' : ''));
      if (!track) return;
      var s = track.getSettings ? track.getSettings() : {};
      var cam = cams.filter(function (d) { return d.deviceId === s.deviceId; })[0];
      var gid = cam && cam.groupId;
      var core = (track.label || '').replace(/\([0-9a-f]{4}:[0-9a-f]{4}\)/i, '').trim().toLowerCase();
      var mics = devices.filter(function (d) {
        if (d.kind !== 'audioinput' || d.deviceId === 'default' || d.deviceId === 'communications') return false;
        if (gid && d.groupId === gid) return true;
        return core.length >= 4 && d.label && d.label.toLowerCase().indexOf(core) !== -1;
      });
      var anyAudio = devices.some(function (d) { return d.kind === 'audioinput'; });
      setChk('Mic', mics.length ? 'Detected' + (mics[0].label ? ' — ' + mics[0].label : '') : (anyAudio ? 'Not detected' : 'Not reported'));
    }).catch(function () {});
  }

  function updateLed() {
    var v = ledSelect.value;
    if (!v || lastStreamOk === null) { setChk('Led', v ? 'Run the check to compare' : 'Choose what your camera light did'); return; }
    if (v === 'none') { setChk('Led', 'No LED — cover the lens when not in use, and check the OS privacy panel for apps using the camera'); return; }
    if (lastStreamOk) {
      setChk('Led', v === 'on' ? 'Working — the light came on while this page used the camera' : 'Light stayed off while the camera streamed — the indicator may be disabled or faulty');
    } else {
      setChk('Led', v === 'on' ? 'Light is on and the camera is busy — another app is using it right now' : 'Light is off — nothing appears to be streaming from the camera');
    }
  }

  function resetResults() {
    Object.keys(chk).forEach(function (k) { if (k !== 'Permission' && k !== 'Cameras') chk[k].textContent = '—'; });
  }

  function releaseStream() {
    if (activeStream) {
      activeStream.getTracks().forEach(function (t) { t.stop(); });
      activeStream = null;
    }
    checkVideo.srcObject = null;
  }

  // Counts delivered frames over SAMPLE_MS and reads one frame for
  // brightness / image mode, then resolves; the caller releases the stream.
  function sampleStream(stream) {
    return new Promise(function (resolve) {
      var frames = 0, start = null, last = null, done = false, handle = null;
      function finish() {
        if (done) return;
        done = true;
        if (handle !== null && checkVideo.cancelVideoFrameCallback) checkVideo.cancelVideoFrameCallback(handle);
        var secs = start !== null && last !== null ? (last - start) / 1000 : 0;
        resolve({ frames: frames, seconds: secs, fps: secs > 0.5 ? frames / secs : null });
      }
      checkVideo.srcObject = stream;
      var playing = checkVideo.play ? checkVideo.play() : null;
      if (playing && playing.catch) playing.catch(function () {});
      if (typeof checkVideo.requestVideoFrameCallback === 'function') {
        var tick = function (now) {
          if (done) return;
          if (start === null) start = now; else frames++;
          last = now;
          handle = checkVideo.requestVideoFrameCallback(tick);
        };
        handle = checkVideo.requestVideoFrameCallback(tick);
      }
      setTimeout(finish, SAMPLE_MS);
    });
  }

  function analysePicture() {
    var w = checkVideo.videoWidth, h = checkVideo.videoHeight;
    if (!w || !h) return null;
    var sw = 96, sh = Math.max(1, Math.round(96 * h / w));
    hiddenCanvas.width = sw;
    hiddenCanvas.height = sh;
    var ctx = hiddenCanvas.getContext('2d');
    ctx.drawImage(checkVideo, 0, 0, sw, sh);
    var d = ctx.getImageData(0, 0, sw, sh).data, n = sw * sh, sum = 0, chroma = 0, minY = 255, maxY = 0;
    for (var i = 0; i < d.length; i += 4) {
      var y = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
      sum += y;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
      if (Math.max(d[i], d[i + 1], d[i + 2]) - Math.min(d[i], d[i + 1], d[i + 2]) > 12) chroma++;
    }
    return { brightness: sum / n, oneColour: maxY - minY < 12, grayscale: chroma / n < 0.02 };
  }

  // Distinguish NotReadableError/NotAllowedError/NotFoundError precisely --
  // each points at a different fix, per this tool's own spec note. Never
  // imply detection of spying; only "another app currently holds it" or
  // "access is blocked" or "no camera exists at all".
  function runCheck() {
    if (running) return;
    running = true;
    resetResults();
    btnRun.disabled = true;
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);

    navigator.mediaDevices.getUserMedia({ video: true, audio: false })
      .then(function (stream) {
        activeStream = stream;
        lastStreamOk = true;
        var track = stream.getVideoTracks()[0];
        setChk('StreamResult', 'Live video track');
        setChk('NextStep', 'Nothing to fix — the camera is free for your call or app.');
        setDiagnostic([{ sev: 'ok', html: '<strong>Your camera is free.</strong> Reading a few seconds of frames, then releasing it…' }]);
        readPermission();
        return readDevices(track).then(function () { return sampleStream(stream); }).then(function (m) {
          var s = track.getSettings ? track.getSettings() : {};
          var w = s.width || checkVideo.videoWidth, h = s.height || checkVideo.videoHeight;
          if (w && h) {
            var g = gcd(w, h) || 1;
            setChk('Resolution', w + '×' + h);
            setChk('Megapixels', (w * h / 1e6).toFixed(2) + ' MP');
            setChk('Standard', videoStandard(w, h));
            setChk('Aspect', (w / g) + ':' + (h / g));
          }
          if (m.fps) {
            setChk('FrameRate', m.fps.toFixed(1) + ' fps (' + m.frames + ' frames / ' + m.seconds.toFixed(1) + ' s)');
            setChk('FpsCheck', m.fps >= 24 ? 'Smooth' : m.fps >= 15 ? 'Low — usually dim lighting' : 'Very low — add light or close other apps');
          } else {
            setChk('FrameRate', s.frameRate ? (Math.round(s.frameRate * 10) / 10) + ' fps (reported)' : 'Not measurable in this browser');
          }
          var pic = null;
          try { pic = analysePicture(); } catch (e) { pic = null; }
          if (pic) {
            setChk('Lighting', Math.round(pic.brightness) + ' / 255 — ' + (pic.brightness < 40 ? 'Very dark (lens covered or no light?)' : pic.brightness < 80 ? 'Dim — add light' : pic.brightness > 220 ? 'Very bright' : 'Good'));
            setChk('ImageMode', pic.oneColour ? 'One-colour fill — lens covered, shutter closed or privacy cover on' : pic.grayscale ? 'Grayscale' : 'Colour');
          }
          releaseStream();
          updateLed();
          setDiagnostic([{ sev: 'ok', html: '<strong>Your camera is free.</strong> Nothing else currently holds an exclusive lock on it, and this page has now released it again. If the indicator light was on a moment ago and now isn’t, whatever was using it likely just released it.' }]);
        });
      })
      .catch(function (err) {
        releaseStream();
        lastStreamOk = false;
        setChk('StreamResult', (err && err.name) || 'Error');
        readPermission();
        readDevices(null);
        var next = {
          NotReadableError: 'Close Zoom, Teams, Meet, OBS or other camera tabs, then run the check again.',
          TrackStartError: 'Close Zoom, Teams, Meet, OBS or other camera tabs, then run the check again.',
          NotAllowedError: 'Allow the camera for this site (address-bar icon) and in your OS privacy settings, then reload.',
          PermissionDeniedError: 'Allow the camera for this site (address-bar icon) and in your OS privacy settings, then reload.',
          NotFoundError: 'Connect a webcam, or enable it in Device Manager / System Settings, then reload.',
          DevicesNotFoundError: 'Connect a webcam, or enable it in Device Manager / System Settings, then reload.',
          SecurityError: 'Open this page over HTTPS.',
        };
        setChk('NextStep', next[err && err.name] || 'Reload the page and try again.');
        updateLed();
        switch (err && err.name) {
          case 'NotReadableError':
          case 'TrackStartError':
            setDiagnostic([{ sev: 'warn', html: '<strong>Your camera is currently in use by another application.</strong> This is the most common cause — a video-call app (Zoom, Teams, Meet) or another browser tab left open in the background. Close other apps that might be using the camera and run the check again.' }]);
            break;
          case 'NotAllowedError':
          case 'PermissionDeniedError':
            setDiagnostic([{ sev: 'error', html: '<strong>Camera access is blocked</strong> — either you denied the permission prompt, or your browser/OS has camera access turned off for this site. This is a permissions setting, not a sign the camera is in use.' }]);
            break;
          case 'NotFoundError':
          case 'DevicesNotFoundError':
            setDiagnostic([{ sev: 'error', html: '<strong>No camera was detected</strong> on this device at all, so this check can’t tell you anything about in-use status.' }]);
            break;
          case 'SecurityError':
            setDiagnostic([{ sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' }]);
            break;
          default:
            setDiagnostic([{ sev: 'error', html: '<strong>Something went wrong running the check.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' }]);
        }
      })
      .finally(function () { running = false; btnRun.disabled = false; });
  }

  btnRun.addEventListener('click', runCheck);
  ledSelect.addEventListener('change', updateLed);

  // Never keep the camera if the visitor leaves mid-check.
  window.addEventListener('pagehide', releaseStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') releaseStream();
  });

  readPermission();
  readDevices(null);
  updateLed();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnRun.disabled = true;
  }
})();
